namespace f=engine::fields;namespace s=engine::smoke;namespace e=engine::effects;using gpu_test::Rig;
namespace {
unsigned checks=0,comparisons=0;
void require(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}
struct Query {
    gpu_test::Com<ID3D12RootSignature> root;gpu_test::Com<ID3D12PipelineState> pipeline;
    explicit Query(Rig& rig){D3D12_ROOT_PARAMETER p[4]{};p[0].ParameterType=D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS;p[0].Constants.Num32BitValues=28;p[1].ParameterType=p[2].ParameterType=D3D12_ROOT_PARAMETER_TYPE_SRV;p[2].Descriptor.ShaderRegister=1;p[3].ParameterType=D3D12_ROOT_PARAMETER_TYPE_UAV;D3D12_ROOT_SIGNATURE_DESC d{};d.NumParameters=4;d.pParameters=p;d.Flags=D3D12_ROOT_SIGNATURE_FLAG_CBV_SRV_UAV_HEAP_DIRECTLY_INDEXED;gpu_test::Com<ID3DBlob> bytes,errors;gpu_test::hr(D3D12SerializeRootSignature(&d,D3D_ROOT_SIGNATURE_VERSION_1,bytes.out(),errors.out()),"Serialize WF query root");gpu_test::hr(rig.device.p->CreateRootSignature(0,bytes.p->GetBufferPointer(),bytes.p->GetBufferSize(),IID_PPV_ARGS(root.out())),"Create WF query root");D3D12_COMPUTE_PIPELINE_STATE_DESC pd{};pd.pRootSignature=root.p;pd.CS={nativegpu::shaders::kFieldQuery.data,nativegpu::shaders::kFieldQuery.size};gpu_test::hr(rig.device.p->CreateComputePipelineState(&pd,IID_PPV_ARGS(pipeline.out())),"Create existing field query PSO");}
    std::vector<f::GpuFieldAnswer> run(Rig& rig,const std::shared_ptr<f::GpuVisualView>& view,const std::vector<f::GpuFieldQuery>& input,f::Tick tick){
        require(!!view,"Missing GPU WF view");const auto b=view->bindings();const auto inputBytes=input.size()*sizeof(f::GpuFieldQuery),bytes=input.size()*sizeof(f::GpuFieldAnswer);gpu_test::Com<ID3D12Resource> requests,output,read;
        gpu_test::makeBuffer(rig.device.p,requests,inputBytes,D3D12_HEAP_TYPE_UPLOAD,D3D12_RESOURCE_STATE_GENERIC_READ);gpu_test::makeBuffer(rig.device.p,read,bytes,D3D12_HEAP_TYPE_READBACK,D3D12_RESOURCE_STATE_COPY_DEST);void* data=nullptr;D3D12_RANGE none{0,0};gpu_test::hr(requests.p->Map(0,&none,&data),"Map WF query requests");std::memcpy(data,input.data(),inputBytes);requests.p->Unmap(0,nullptr);
        D3D12_HEAP_PROPERTIES heap{};heap.Type=D3D12_HEAP_TYPE_DEFAULT;heap.CreationNodeMask=heap.VisibleNodeMask=1;D3D12_RESOURCE_DESC desc{};desc.Dimension=D3D12_RESOURCE_DIMENSION_BUFFER;desc.Width=bytes;desc.Height=1;desc.DepthOrArraySize=desc.MipLevels=1;desc.SampleDesc.Count=1;desc.Layout=D3D12_TEXTURE_LAYOUT_ROW_MAJOR;desc.Flags=D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS;gpu_test::hr(rig.device.p->CreateCommittedResource(&heap,D3D12_HEAP_FLAG_NONE,&desc,D3D12_RESOURCE_STATE_UNORDERED_ACCESS,nullptr,IID_PPV_ARGS(output.out())),"Create WF query output");
        rig.begin();require(view->markUsed(rig.ticket()),"WF query actual fence rejected");ID3D12DescriptorHeap* heaps[]={b.descriptors};rig.commands.p->SetDescriptorHeaps(1,heaps);rig.commands.p->SetComputeRootSignature(root.p);rig.commands.p->SetPipelineState(pipeline.p);auto constants=b.constants(input.size(),tick);rig.commands.p->SetComputeRoot32BitConstants(0,28,constants.data(),0);rig.commands.p->SetComputeRootShaderResourceView(1,b.pageTable);rig.commands.p->SetComputeRootShaderResourceView(2,requests.p->GetGPUVirtualAddress());rig.commands.p->SetComputeRootUnorderedAccessView(3,output.p->GetGPUVirtualAddress());rig.commands.p->Dispatch((input.size()+63)/64,1,1);gpu_test::transition(rig.commands.p,output.p,D3D12_RESOURCE_STATE_UNORDERED_ACCESS,D3D12_RESOURCE_STATE_COPY_SOURCE);rig.commands.p->CopyBufferRegion(read.p,0,output.p,0,bytes);rig.submit();
        D3D12_RANGE range{0,bytes};gpu_test::hr(read.p->Map(0,&range,&data),"Map completed WF validation");std::vector<f::GpuFieldAnswer> result(input.size());std::memcpy(result.data(),data,bytes);read.p->Unmap(0,&none);return result;
    }
};

std::vector<f::Channel> catalog(){return {{"particleDensity","particle-q","effects",f::Domain::VisualReference,f::Merge::Sum,0,1000000,1000},{"smokeDensity","kg/m^3","smoke",f::Domain::VisualReference,f::Merge::Sum,0,1048576,1024},{"hazard","damage/s","game",f::Domain::CpuAuthority,f::Merge::Sum,0,65535,1000}};}
e::Emitter emitter(){e::Emitter p;p.id="joint-particles";p.position={.25f,.25f,.25f};p.lifeMin=p.lifeMax=240;e::Module init;init.size={.1f,.1f};p.modules={init};p.renderers.push_back({"sprite","test.png","","",e::Blend::Additive,false});return p;}
s::Spec smokeSpec(){s::Spec p;p.channels=s::Density;p.dimensions={2,2,2};p.cellMetres=.5f;p.originMetres={};p.maxDensity=10;p.densityDecay=p.cooling=p.fuelDecay=p.burnRate=p.buoyancy=p.smokeWeight=p.vorticity=0;p.maxSpeed=1;p.pressureIterations=4;p.macCormack=false;return p;}
f::LocalSpec local(const char* owner,unsigned channel){f::LocalSpec p;p.owner=owner;p.source=1;p.dimensions={2,2,2};p.finePerWorld=2;p.channels={{channel,f::ProjectionReduction::VolumeAverage}};return p;}
f::GpuSharingHandle track(f::GpuFieldSharing& sharing,const char* owner){const auto result=sharing.create({owner,1,8,6});require(result.result.accepted(),result.result.error.c_str());return result.handle;}
void sample(Rig& rig,Query& query,const std::shared_ptr<f::GpuVisualView>& view,f::Tick tick,int particles,int smoke,std::uint64_t version,bool retiredParticles=false,bool retiredSmoke=false){
    auto result=query.run(rig,view,{{0,0,0,0},{0,0,0,1}},tick);require(result.size()==2,"Joint query count");
    const int values[]={particles,smoke};const bool retired[]={retiredParticles,retiredSmoke};for(unsigned i=0;i<2;++i){const auto& answer=result[i];require(answer.status==unsigned(retired[i]?f::Status::Unavailable:f::Status::Ok)&&answer.value==values[i]&&((std::uint64_t(answer.versionHigh)<<32)|answer.versionLow)==version,"Two-domain snapshot value/status/version mismatch");++comparisons;}
}
void run(Rig& rig){
    auto c=catalog();f::GpuVisualWorld world(rig.device.p,rig.fence.p,c);f::GpuFieldSharing particles(world,4),smoke(world,4);f::GpuFieldTransaction batch(world,{&particles,&smoke});auto ph=track(particles,"effects"),sh=track(smoke,"smoke");
    f::LeaseRequest read;read.owner="joint-reader";read.region={{0,0,0},{1,1,1}};read.channels={0,1};read.maxPages=8;read.maxAgeTicks=6;auto reader=world.acquire(read);require(reader.accepted,reader.error.c_str());auto authority=read;authority.channels={2};authority.consistency=f::Consistency::Strong;require(!world.acquire(authority).accepted,"Visual world granted authority/Strong");
    f::GpuLocalFields particleFields(rig.device.p,rig.fence.p,c),smokeFields(rig.device.p,rig.fence.p,c);f::GpuLocalHandle pf,sf;std::string error;require(particleFields.create(local("effects",0),pf,error)&&smokeFields.create(local("smoke",1),sf,error),error.c_str());e::GpuParticlePool pool(rig.device.p,emitter(),8);const auto spec=smokeSpec();s::GpuSmokeFireSolver solver(rig.device.p,rig.fence.p,spec);auto initial=s::initialState(spec);std::fill(initial.scalars.begin(),initial.scalars.end(),.25f);require(solver.setInputs(std::vector<s::CellInput>(8),error,&initial),error.c_str());
    rig.begin();require(pool.initialize(rig.commands.p,rig.ticket(),error)&&pool.step(rig.commands.p,rig.ticket(),0,4,0,41,{},error),error.c_str());require(particleFields.begin(pf,rig.commands.p,rig.ticket(),0,error)&&particleFields.splat(pf,0,pool,32,rig.commands.p,rig.ticket(),error)&&particleFields.resolve(pf,rig.commands.p,rig.ticket(),error),error.c_str());require(solver.step(rig.commands.p,rig.ticket(),0,1.f/120,error)&&smokeFields.replaceScalar(sf,s::densityFieldInput(solver),rig.commands.p,rig.ticket(),error),error.c_str());auto p0=particleFields.project(pf,0,rig.commands.p,rig.ticket(),error),s0=smokeFields.project(sf,0,rig.commands.p,rig.ticket(),error);require(p0&&s0,error.c_str());require(batch.begin(error)&&particles.promote(ph,p0,0).accepted()&&smoke.promote(sh,s0,0).accepted(),"Cannot publish real particle and smoke outputs together");require(batch.commit(rig.commands.p,rig.ticket(),0,error).accepted(),error.c_str());rig.submit();require(particles.settle(ph).accepted()&&smoke.settle(sh).accepted(),"Joint producer acknowledgment");auto old=world.view(reader.lease,error);require(!!old,error.c_str());Query query(rig);sample(rig,query,old,0,16,256,1);require(world.stats().commits==1&&world.subscribers(read.region,{0})==1&&world.subscribers(read.region,{1})==1,"Shared catalog/read demand split by producer");
    auto wrongCatalog=c;wrongCatalog[1].unitsPerInteger=1000;f::GpuLocalFields wrongFields(rig.device.p,rig.fence.p,wrongCatalog);f::GpuLocalHandle wrong;require(wrongFields.create(local("smoke",1),wrong,error),error.c_str());std::vector<s::CellInput> rates(8);for(auto& cell:rates)cell.densityRate=30;require(solver.setInputs(rates,error),error.c_str());
    rig.begin();require(particleFields.begin(pf,rig.commands.p,rig.ticket(),1,error)&&particleFields.splat(pf,0,pool,64,rig.commands.p,rig.ticket(),error)&&particleFields.resolve(pf,rig.commands.p,rig.ticket(),error),error.c_str());require(solver.step(rig.commands.p,rig.ticket(),1,1.f/120,error)&&smokeFields.replaceScalar(sf,s::densityFieldInput(solver),rig.commands.p,rig.ticket(),error)&&wrongFields.replaceScalar(wrong,s::densityFieldInput(solver),rig.commands.p,rig.ticket(),error),error.c_str());auto p1=particleFields.project(pf,1,rig.commands.p,rig.ticket(),error),s1=smokeFields.project(sf,1,rig.commands.p,rig.ticket(),error),invalid=wrongFields.project(wrong,1,rig.commands.p,rig.ticket(),error);require(p1&&s1&&invalid,error.c_str());require(batch.begin(error)&&particles.project(ph,p1,1).accepted(),"Cannot stage first domain");const auto rejected=smoke.project(sh,invalid,1);require(!rejected.accepted()&&rejected.publication==f::PublishResult::AccessDenied,"Same-name mismatched density units were silently converted");batch.rollback();require(world.stats().commits==1&&particles.inspect(ph).acknowledgedEpoch==1&&smoke.inspect(sh).acknowledgedEpoch==1&&!particles.inspect(ph).pending&&!smoke.inspect(sh).pending,"Rejected channel metadata leaked partial publication");rig.submit();sample(rig,query,old,1,16,256,1);
    rig.begin();require(batch.begin(error)&&particles.project(ph,p1,1).accepted()&&smoke.project(sh,s1,1).accepted(),"Cannot retry matching data without re-simulation");require(batch.commit(rig.commands.p,rig.ticket(),1,error).accepted(),error.c_str());rig.submit();require(particles.settle(ph).accepted()&&smoke.settle(sh).accepted(),"Joint update acknowledgment");auto current=world.view(reader.lease,error);require(!!current,error.c_str());sample(rig,query,current,1,32,512,2);sample(rig,query,old,0,16,256,1);require(world.sourceView("effects",1).version==world.sourceView("smoke",1).version&&solver.buffers().sourceTick==1,"Independent source namespaces or ticks diverged in one snapshot");
    rig.begin();require(batch.begin(error)&&particles.retire(ph,2).accepted(),"Particle-only retirement");require(batch.commit(rig.commands.p,rig.ticket(),2,error).accepted(),error.c_str());rig.submit();require(particles.settle(ph).accepted(),"Particle withdrawal acknowledgment");auto survivor=world.view(reader.lease,error);require(!!survivor,error.c_str());sample(rig,query,survivor,2,0,512,3,true);sample(rig,query,current,1,32,512,2);
    rig.begin();require(batch.begin(error)&&smoke.retire(sh,3).accepted(),"Final smoke retirement");require(batch.commit(rig.commands.p,rig.ticket(),3,error).accepted(),error.c_str());rig.submit();require(smoke.settle(sh).accepted(),"Smoke withdrawal acknowledgment");auto empty=world.view(reader.lease,error);require(!!empty,error.c_str());sample(rig,query,empty,3,0,0,4,true,true);old.reset();current.reset();survivor.reset();empty.reset();require(world.release(reader.lease,error)&&world.shutdown(error),error.c_str());require(world.context().device==nullptr&&world.context().catalog.empty(),"Stopped world exposed stale context");p0.reset();s0.reset();p1.reset();s1.reset();invalid.reset();particleFields.collect();smokeFields.collect();wrongFields.collect();require(particleFields.shutdown(error)&&smokeFields.shutdown(error)&&wrongFields.shutdown(error)&&pool.shutdown(rig.submitted,error)&&solver.shutdown(error),error.c_str());
}
}
int main(int argc,char** argv){try{std::string adapter;if(argc==3&&std::string(argv[1])=="--adapter")adapter=argv[2];else if(argc!=1)throw std::runtime_error("Usage: native_field_joint_gpu_tests [--adapter substring]");Rig rig(adapter);require(rig.debug,"Hardware debug layer required");run(rig);const auto errors=rig.debugErrors();require(errors==0,"Joint field D3D12 errors");std::cout<<nlohmann::json{{"schema","nativegpu.field-joint-gpu-evidence/1"},{"ok",true},{"groups",1},{"checks",checks},{"comparisons",comparisons},{"adapter",rig.adapter},{"debugLayer",rig.debug},{"debugErrors",errors},{"oneVisualWorld",true},{"distinctTypedChannels",true},{"runtimeReadback",false},{"scope","Actual GPU particles and solved smoke publish in one typed visual WF and one joint snapshot. Production-service/renderer migration and CPU authority integration remain pending."}}.dump()<<'\n';}catch(const std::exception& e){std::cerr<<"Joint fields failed after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
